t.script:
//
lucide.createIcons();

    function openModal(titleText) {
      document.getElementById('modal-input-platform').value = titleText;
      document.getElementById('modal-title').innerText = titleText;
      const m = document.getElementById('modal-container');
      m.classList.remove('hidden');
      m.classList.add('flex');
    }

    function closeModal() {
      const m = document.getElementById('modal-container');
      m.classList.add('hidden');
      m.classList.remove('flex');
      document.getElementById('modal-form').classList.remove('hidden');
      document.getElementById('modal-success').classList.add('hidden');
    }

    function handleInquirySubmit(e) {
      e.preventDefault();
      document.getElementById('modal-form').classList.add('hidden');
      document.getElementById('modal-success').classList.remove('hidden');
      lucide.createIcons();
    }

    function calculateAcademy() {
      const sel = document.getElementById('acad-program');
      const opt = sel.options[sel.selectedIndex];
      const price = parseInt(opt.getAttribute('data-price') || '35000', 10);
      const isPerSeat = opt.getAttribute('data-is-per-seat') === 'true';
      const duration = opt.getAttribute('data-duration') || '4 Weeks';
      const seats = parseInt(document.getElementById('acad-seats').value || '5', 10);

      document.getElementById('seats-display').innerText = seats + (seats === 1 ? ' Seat' : ' Seats');

      let total = isPerSeat ? (price * seats) : price;

      document.getElementById('acad-total-etb').innerHTML = 
        total.toLocaleString() + ' <span class="text-lg text-slate-400">ETB</span>';
      document.getElementById('acad-duration').innerText = duration;
      lucide.createIcons();
    }

    window.addEventListener('DOMContentLoaded', calculateAcademy);
//
